<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import type { EChartsCoreOption } from 'echarts/core';import { apiGet } from '../api/client';import AdminChart from '../components/AdminChart.vue';import KpiGrid from '../components/KpiGrid.vue';import PageHeader from '../components/PageHeader.vue';import type { AnalyticsData } from '../types/admin'
const data=ref<AnalyticsData>();const loading=ref(true)
const fmtWan=(v?:number)=>v===undefined?'—':`${(v/10000).toFixed(1)}w`;const pct=(v?:number)=>v===undefined?'—':`${(v*100).toFixed(1)}%`
const kpis=computed(()=>[{label:'总曝光',value:fmtWan(data.value?.summary.impressions),delta:'+9.2%'},{label:'总点击',value:fmtWan(data.value?.summary.clicks),delta:'+11.8%'},{label:'平均 CTR',value:pct(data.value?.summary.ctr),delta:'+1.4pp'},{label:'收藏转化',value:pct(data.value?.summary.favoriteConversion),delta:'行为转化'}])
const option=computed<EChartsCoreOption>(()=>({tooltip:{trigger:'axis'},legend:{data:['曝光','点击']},grid:{left:50,right:24,top:48,bottom:36},xAxis:{type:'category',data:(data.value?.trend||[]).map(x=>new Date(x.date).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'}))},yAxis:{type:'value'},series:[{name:'曝光',type:'bar',data:(data.value?.trend||[]).map(x=>x.impressions),itemStyle:{color:'#1a1a1a',borderRadius:[4,4,0,0]}},{name:'点击',type:'line',smooth:true,data:(data.value?.trend||[]).map(x=>x.clicks),lineStyle:{color:'#a8d300',width:3},itemStyle:{color:'#a8d300'}}]}))
async function load(){loading.value=true;try{data.value=await apiGet<AnalyticsData>('/admin/analytics')}finally{loading.value=false}};onMounted(load)
</script>
<template><PageHeader title="曝光与点击" group="数据中心" description="基于 daily_metrics 与路线统计的运营分析"><el-button :loading="loading" @click="load">刷新</el-button></PageHeader><KpiGrid :items="kpis" :loading="loading"/><div class="chart-grid"><section class="panel"><div class="panel__toolbar"><span class="panel__title">每日曝光与点击趋势</span><span class="muted">数据库日聚合</span></div><div class="panel__body"><AdminChart v-if="data" :option="option" :height="340"/></div></section><section class="panel"><div class="panel__toolbar"><span class="panel__title">Top 路线 · 曝光</span></div><el-table :data="data?.topRoutes||[]" height="376"><el-table-column type="index" label="#" width="52"/><el-table-column prop="title" label="路线" min-width="180" show-overflow-tooltip/><el-table-column label="曝光" width="90"><template #default="{row}">{{fmtWan(row.impressions)}}</template></el-table-column><el-table-column label="CTR" width="80"><template #default="{row}">{{pct(row.ctr)}}</template></el-table-column></el-table></section></div></template>
